  const all = [];
  walls.forEach((p) => (p.points || []).forEach((q) => all.push(q)));
  wets.forEach((p) => (p.points || []).forEach((q) => all.push(q)));
  equip.forEach((e) => all.push([e.x, e.y]));
  pins.forEach((m) => all.push([m.x, m.y]));
