    const ex = P1[0] - P0[0], ey = P1[1] - P0[1], len = Math.hypot(ex, ey) || 1;
    const dir = [ex / len, ey / len]; let nrm = [-dir[1], dir[0]];
    const cx = P0[0] + op.t * ex, cy = P0[1] + op.t * ey;
