    P.push(`<line x1="${N(fx(A[0]))}" y1="${N(fy(A[1]))}" x2="${N(fx(B[0]))}" y2="${N(fy(B[1]))}" stroke="#F59E0B" stroke-width="6" stroke-linecap="round" stroke-dasharray="2 6" opacity="0.95"/>`);
